<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';
import {useApplication} from '../../application';
import {useMinutesGeneration} from './useMinutesGeneration';
import {ApiError} from '../../shared/api/client';
const application=useApplication();
const props=defineProps<{meetingId:string;autoStart?:boolean}>(),{session,minutesGeneration,workspace,journals,generationScopeReady,meetingScope}=useApplication();
const emit=defineEmits<{changed:[];started:[]}>();
const actor=()=>session.current.value?.actor.enterpriseId??null,eligible=()=>generationScopeReady.value&&meetingScope.value===props.meetingId;
const state=useMinutesGeneration({...minutesGeneration,authorize:async(id,signal)=>{const nav=await workspace.navigation(id,signal);if(nav.relation!=='OWNER'||nav.navigationState!=='CHECK_PRODUCER')throw new ApiError('http',403,'当前身份或会议状态不允许生成。');return nav;}},actor,()=>props.meetingId,eligible,journals);
watch(()=>state.current.value,value=>{if(value?.observation.currentMinutesRevisionId)emit('changed');});
const localControlled=import.meta.env.DEV&&import.meta.env.VITE_LOCAL_DEV_LOGIN==='1';
const selection=ref(''),localError=ref<string|null>(null),message=computed(()=>localError.value??(state.error.value instanceof Error?state.error.value.message:null));
const stop=watch(()=>[actor(),props.meetingId,eligible()],()=>{selection.value='';localError.value=null;if(actor()&&eligible())void state.reload();},{immediate:true,flush:'sync'}),stopLogout=session.onLogout(state.logout);
const pending=computed(()=>!['EMPTY','ACKNOWLEDGED','CONFLICT','REJECTED'].includes(state.command.state.value));
const reasons:Record<string,string>={CAPABILITY_UNAVAILABLE:'纪要生成服务暂不可用，请稍后重试',TRANSCRIPT_CONFIRMATION_REQUIRED:'请先确认已保存转写',SETTINGS_REQUIRED:'请先选择初始模板与设置',MINUTES_COMBINED_NOT_INSTALLED:'纪要生成服务尚不可用',GENERATION_REQUIRED:'当前内容需要重新生成',PUBLISHED:'会议已经发布'};
function discard(){try{localError.value=null;state.discardRejected();void state.reload();}catch(cause){localError.value=cause instanceof Error?cause.message:'原操作暂无法清理。';}}
let autoStarted=false,templateRequested=false,pollTimer:ReturnType<typeof setTimeout>|null=null,pollEpoch=0;
async function generate(){if(pending.value||state.busy.value||state.blocked.value)return;if(!state.current.value?.saved.templateRevisionId){if(!state.templates.value)await state.loadTemplates(false);if(!selection.value)selection.value=state.templates.value?.items.find(t=>t.selectable&&t.default)?.revisionId??state.templates.value?.items.find(t=>t.selectable)?.revisionId??'';if(!selection.value)return;await state.initialize(selection.value);if(state.error.value||!state.current.value?.saved.templateRevisionId)return;}await state.generate();}
watch(()=>props.autoStart,value=>{if(!value)autoStarted=false;});
watch(()=>[props.autoStart,state.current.value,state.loading.value,state.busy.value],()=>{if(!state.current.value||state.loading.value||state.busy.value)return;if(props.autoStart&&!autoStarted&&!pending.value){autoStarted=true;void generate();}else if(!props.autoStart&&!state.current.value.saved.templateRevisionId&&!templateRequested){templateRequested=true;void state.loadTemplates(false).then(()=>{selection.value=state.templates.value?.items.find(t=>t.default&&t.selectable)?.revisionId??'';});}});
watch(()=>state.command.ack.value?.result,ack=>{if(ack?.kind!=='GENERATION_TASK')return;emit('started');const turn=++pollEpoch,taskId=ack.taskId,id=props.meetingId,who=actor();let count=0;async function tick(){if(turn!==pollEpoch||who!==actor()||id!==props.meetingId)return;try{const page=await application.tasks.list(id,'MINUTES_GENERATE_V1',null,new AbortController().signal);if(turn!==pollEpoch)return;const task=page.items.find(t=>t.taskId===taskId);if(task&&['SUCCEEDED','FAILED','STALE','CANCELLED'].includes(task.state)){await state.reload();if(task.state!=='SUCCEEDED')emit('changed');return;}}catch{/* The refresh control remains available after a failed observation. */}if(++count<30&&turn===pollEpoch)pollTimer=setTimeout(tick,2000);}pollTimer=setTimeout(tick,1000);});
defineExpose({generate});
onUnmounted(()=>{pollEpoch++;if(pollTimer)clearTimeout(pollTimer);stop();stopLogout();state.dispose();});
</script><template><section class="card generation-panel"><h2>生成会议纪要</h2><p class="muted">基于已确认的会议转写生成核心要素和会议纪要。</p><p v-if="localControlled" class="controlled-provider-note small muted">本地受控模型输出为合成示例，需人工核对。</p><p v-if="message" role="alert">{{message}}</p><p v-if="state.loading.value" role="status">正在检查生成条件…</p><p v-if="pending" role="status">原请求结果待确认，请恢复原操作后继续。</p><template v-if="state.current.value"><label v-if="!state.current.value.saved.templateRevisionId">纪要模板<select v-model="selection" :disabled="state.busy.value||pending"><option value="">请选择模板</option><option v-for="item in state.templates.value?.items" :key="item.revisionId" :value="item.revisionId" :disabled="!item.selectable">{{item.name}}{{item.default?'（默认）':''}}</option></select></label><button v-if="!state.templates.value&&!state.current.value.saved.templateRevisionId" class="btn sm" :disabled="state.loading.value" @click="state.loadTemplates(false)">重新读取模板</button><ul v-if="!state.current.value.eligible"><li v-for="reason in state.current.value.reasons.filter(r=>r!=='SETTINGS_REQUIRED')" :key="reason">{{reasons[reason]??reason}}</li></ul><button class="btn primary" :disabled="state.busy.value||state.loading.value||pending||state.blocked.value||!state.current.value.eligible&&!(!state.current.value.saved.templateRevisionId&&!!selection&&state.current.value.reasons.every(r=>r==='SETTINGS_REQUIRED'))" @click="generate">生成完整纪要</button></template><p v-if="state.command.ack.value?.result.kind==='GENERATION_TASK'" class="small" role="status">生成任务已受理：{{state.command.ack.value.result.taskId}}。完成后显示真实生成结果。</p><details class="mt16"><summary class="small muted">状态与恢复</summary><button v-if="pending" class="btn" :disabled="state.busy.value||state.blocked.value" @click="state.retry">恢复原请求</button><button v-if="['CONFLICT','REJECTED'].includes(state.command.state.value)" class="btn" :disabled="state.busy.value" @click="discard">清除已拒绝请求并重新读取</button><button class="btn" :disabled="state.loading.value||state.busy.value" @click="state.reload">刷新生成条件</button></details></section></template>
<style scoped>.generation-panel{padding:24px;margin:16px}.generation-panel h2{font-size:18px;margin:0 0 12px}.generation-panel .btn{margin-top:12px}label{display:block;margin:16px 0}select{display:block;width:100%;max-width:500px;margin-top:8px;padding:10px;font:inherit;border:1px solid var(--border2);border-radius:6px}.muted{color:var(--muted)}p{margin-top:10px;overflow-wrap:anywhere}.generation-panel ul{padding-left:20px;margin:12px 0}</style>
